parameters.command:
=set -eu
execution_id='{{$execution.id}}'
case "$execution_id" in
  ''|*[!A-Za-z0-9_-]*) echo 'Invalid n8n execution ID' >&2; exit 64 ;;
esac
repo_dir="/tmp/crunchy-calendar-$execution_id"
cleanup() { rm -rf -- "$repo_dir"; }
trap cleanup EXIT HUP INT TERM
command -v python3 >/dev/null 2>&1 || { echo 'python3 is not installed on the n8n execution host' >&2; exit 69; }
test -f "$repo_dir/crunchy_calendar/__main__.py" || { echo 'Git checkout does not contain crunchy_calendar/__main__.py' >&2; exit 66; }
test -f "$repo_dir/data/watching.json" || { echo 'Git checkout does not contain data/watching.json' >&2; exit 66; }
test -f "$repo_dir/data/languages.json" || { echo 'Git checkout does not contain data/languages.json' >&2; exit 66; }
cd "$repo_dir"
python3 -m crunchy_calendar --watching data/watching.json --languages data/languages.json --format json

parameters.jsCode:
const result = $input.first().json;
if (result.exitCode !== undefined && result.exitCode !== 0) {
  throw new Error(`Python forecast failed with exit code ${result.exitCode}: ${result.stderr || 'no stderr'}`);
}
if (typeof result.stdout !== 'string' || !result.stdout.trim()) {
  throw new Error('Python forecast returned empty stdout');
}
let payload;
try {
  payload = JSON.parse(result.stdout);
} catch (error) {
  throw new Error(`Python forecast returned invalid JSON: ${error.message}`);
}
if (payload.contract_version !== 1 || payload.predicted !== true || !Array.isArray(payload.releases)) {
  throw new Error('Python forecast returned an unsupported contract');
}
return [{ json: payload }];
